import{_ as c,r as t,o as l,c as u,e,a as n,s as d,d as s}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"计划任务 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"定义时间表","slug":"定义时间表","link":"#定义时间表","children":[{"level":3,"title":"计划频率选项","slug":"计划频率选项","link":"#计划频率选项","children":[{"level":4,"title":"真值测试约束","slug":"真值测试约束","link":"#真值测试约束","children":[]}]},{"level":3,"title":"防止任务重叠","slug":"防止任务重叠","link":"#防止任务重叠","children":[]}]},{"level":2,"title":"任务输出","slug":"任务输出","link":"#任务输出","children":[]},{"level":2,"title":"任务钩子","slug":"任务钩子","link":"#任务钩子","children":[{"level":4,"title":"Ping URL","slug":"ping-url","link":"#ping-url","children":[]}]}],"relativePath":"2.x/zh-cn/plugin/scheduling.md","filePath":"2.x/zh-cn/plugin/scheduling.md"}'),i={name:"2.x/zh-cn/plugin/scheduling.md"};function r(k,a,g,h,f,m){const p=t("pre-heading"),o=t("post-heading");return l(),u("div",null,[e(p),a[0]||(a[0]=n("h1",null,"计划任务",-1)),e(o),a[1]||(a[1]=d(`<p>过去，开发人员会为他们需要安排的每个任务生成一个 Cron 条目。然而，这有时会让人头疼。您的计划任务不再受源代码控制，您必须通过 SSH 连接到您的服务器才能添加 Cron 条目。命令调度程序允许您在应用程序本身中流畅而明确地定义命令调度，并且您的服务器上只需要一个 Cron 条目。</p><blockquote><p><strong>注意</strong>：有关如何设置计划任务的说明，请参阅<a href="./../setup/installation.html#oc-setting-up-the-scheduler">安装指南</a>。</p></blockquote><p><a id="oc-defining-schedules"></a></p><h2 id="定义时间表"><a href="#定义时间表" class="header-anchor">#</a> 定义时间表</h2><p>您可以通过覆盖<a href="./registration.html#oc-registration-file">插件注册类</a> 中的<code>registerSchedule</code> 方法来定义所有计划任务。该方法将采用单个 <code>$schedule</code> 参数，用于定义命令及其频率。</p><p>首先，让我们看一个计划任务的示例。在这个例子中，我们将安排一个 <code>Closure</code> 每天午夜调用。在 <code>Closure</code> 中，我们将执行一个数据库查询来清除一个表：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Plugin</span> <span class="token keyword">extends</span> <span class="token class-name">PluginBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">// ...</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerSchedule</span><span class="token punctuation">(</span><span class="token variable">$schedule</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Db</span><span class="token operator">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;recent_users&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>除了调度<code>Closure</code>调用，你还可以调度<a href="./../console/commands.html">控制台命令</a>和操作系统命令。 例如，您可以使用 <code>command</code> 方法来调度控制台命令：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;cache:clear&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>exec</code> 命令可用于向操作系统发出命令：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">exec</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;node /home/acme/script.js&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="计划频率选项"><a href="#计划频率选项" class="header-anchor">#</a> 计划频率选项</h3><p>当然，您可以为您的任务分配多种时间表：</p><div class="table"><table tabindex="0"><thead><tr><th>方法</th><th>描述</th></tr></thead><tbody><tr><td><code>-&gt;cron(&#39;* * * * *&#39;);</code></td><td>按自定义 Cron 计划运行任务</td></tr><tr><td><code>-&gt;everyMinute();</code></td><td>每分钟运行一次任务</td></tr><tr><td><code>-&gt;everyFiveMinutes();</code></td><td>每五分钟运行一次任务</td></tr><tr><td><code>-&gt;everyTenMinutes();</code></td><td>每十分钟运行一次任务</td></tr><tr><td><code>-&gt;everyThirtyMinutes();</code></td><td>每三十分钟运行一次任务</td></tr><tr><td><code>-&gt;hourly();</code></td><td>每小时运行一次任务</td></tr><tr><td><code>-&gt;daily();</code></td><td>每天午夜运行任务</td></tr><tr><td><code>-&gt;dailyAt(&#39;13:00&#39;);</code></td><td>每天13:00运行任务</td></tr><tr><td><code>-&gt;twiceDaily(1, 13);</code></td><td>每天 1:00 和 13:00 运行任务</td></tr><tr><td><code>-&gt;weekly();</code></td><td>每周运行任务</td></tr><tr><td><code>-&gt;monthly();</code></td><td>每月运行任务</td></tr></tbody></table></div><p>这些方法可以与额外的约束相结合，以创建仅在一周中的某些天运行的更精细调整的计划。 例如，要安排命令在每周星期一运行：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">call</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 每周一在 13:00 运行一次...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">weekly</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">mondays</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">at</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;13:00&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>以下是附加计划限制的列表：</p><div class="table"><table tabindex="0"><thead><tr><th>方法</th><th>描述</th></tr></thead><tbody><tr><td><code>-&gt;weekdays();</code></td><td>将任务限制在工作日</td></tr><tr><td><code>-&gt;sundays();</code></td><td>将任务限制在周日</td></tr><tr><td><code>-&gt;mondays();</code></td><td>将任务限制在星期一</td></tr><tr><td><code>-&gt;tuesdays();</code></td><td>将任务限制在星期二</td></tr><tr><td><code>-&gt;wednesdays();</code></td><td>将任务限制在周三</td></tr><tr><td><code>-&gt;thursdays();</code></td><td>将任务限制在星期四</td></tr><tr><td><code>-&gt;fridays();</code></td><td>将任务限制在周五</td></tr><tr><td><code>-&gt;saturdays();</code></td><td>将任务限制在星期六</td></tr><tr><td><code>-&gt;when(Closure);</code></td><td>根据真值测试限制任务</td></tr></tbody></table></div><h4 id="真值测试约束"><a href="#真值测试约束" class="header-anchor">#</a> 真值测试约束</h4><p><code>when</code> 方法可用于根据给定真值测试的结果限制任务的执行。 换句话说，如果给定的 <code>Closure</code> 返回 <code>true</code>，只要没有其他约束条件阻止任务运行，任务就会执行：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">when</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="防止任务重叠"><a href="#防止任务重叠" class="header-anchor">#</a> 防止任务重叠</h3><p>默认情况下，即使任务的前一个实例仍在运行，计划任务也会运行。 为了防止这种情况，您可以使用 <code>withoutOverlapping</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">withoutOverlapping</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在这个例子中，如果<code>emails:send</code> <a href="./../console/commands.html">控制台命令</a> 尚未运行，它将每分钟运行一次。 如果您的任务的执行时间变化很大，则<code>withoutOverlapping</code>方法特别有用，这使您无需准确预测给定任务将花费多长时间。</p><h2 id="任务输出"><a href="#任务输出" class="header-anchor">#</a> 任务输出</h2><p>调度程序提供了几种方便的方法来处理调度任务生成的输出。 首先，使用 <code>sendOutputTo</code> 方法，您可以将输出发送到文件以供以后检查：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">sendOutputTo</span><span class="token punctuation">(</span><span class="token variable">$filePath</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>使用 <code>emailOutputTo</code> 方法，您可以将输出通过电子邮件发送到您选择的电子邮件地址。 请注意，必须首先使用 <code>sendOutputTo</code> 方法将输出发送到文件。 同样在通过电子邮件发送任务输出之前，您应该配置 <a href="./../services/mail.html">邮件服务</a>：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">sendOutputTo</span><span class="token punctuation">(</span><span class="token variable">$filePath</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">emailOutputTo</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo@example.com&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>注意</strong>：<code>emailOutputTo</code> 和<code>sendOutputTo</code> 方法是<code>command</code> 方法独有的，<code>call</code> 不支持。</p></blockquote><h2 id="任务钩子"><a href="#任务钩子" class="header-anchor">#</a> 任务钩子</h2><p>使用 <code>before</code> 和 <code>after</code> 方法，你可以指定在计划任务完成之前和之后执行的代码：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">before</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// 任务即将开始……</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">after</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// 任务完成...</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="ping-url"><a href="#ping-url" class="header-anchor">#</a> Ping URL</h4><p>使用<code>pingBefore</code> 和<code>thenPing</code> 方法，调度程序可以在任务完成之前或之后自动ping 给定的URL。 此方法可用于通知外部服务您的计划任务正在开始或完成：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$schedule</span><span class="token operator">-&gt;</span><span class="token function">command</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;emails:send&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">daily</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">pingBefore</span><span class="token punctuation">(</span><span class="token variable">$url</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">thenPing</span><span class="token punctuation">(</span><span class="token variable">$url</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,37)),a[2]||(a[2]=n("blockquote",null,[n("p",null,[s("您需要先安装 "),n("a",{href:"https://octobercms.com/plugin/october-drivers",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[s("Drivers 插件"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),n("span",{class:"sr-only"},"(opens new window)")])]),s("，然后才能使用 "),n("code",null,"pingBefore($url)"),s(" 或 "),n("code",null,"thenPing($url)"),s(" 功能。")])],-1))])}const b=c(i,[["render",r]]);export{y as __pageData,b as default};
